import flask
from flask import request, jsonify
import subprocess
import os
import re
import hashlib

app = flask.Flask(__name__)

# Configuration for internal diagnostic service
DIAG_TOOLS = {
    'ping': '/usr/bin/ping',
    'traceroute': '/usr/bin/traceroute',
    'dig': '/usr/bin/dig',
    'nslookup': '/usr/bin/nslookup'
}

ALLOWED_TARGETS_PATTERN = re.compile(r'^[a-zA-Z0-9][a-zA-Z0-9.\-]{0,253}[a-zA-Z0-9]$')

def validate_api_key(key):
    """Validate API key against stored hash - timing safe comparison"""
    expected = os.environ.get('DIAG_API_KEY_HASH', '')
    return hashlib.sha256(key.encode()).hexdigest() == expected

def sanitize_count(count_param):
    """Ensure count is a reasonable integer"""
    try:
        c = int(count_param)
        return max(1, min(c, 10))
    except (ValueError, TypeError):
        return 4

@app.before_request
def check_auth():
    key = request.headers.get('X-Diag-Key', '')
    if not validate_api_key(key):
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/api/v1/diagnose', methods=['POST'])
def diagnose():
    """Run network diagnostic tool against specified target.

    Accepts JSON body:
      - tool: one of ping, traceroute, dig, nslookup
      - target: hostname or IP
      - count: number of packets (ping only)
      - options: additional flags (string)
    """
    data = request.get_json(force=True)

    tool = data.get('tool', '').lower()
    target = data.get('target', '')
    count = sanitize_count(data.get('count'))
    options = data.get('options', '')

    if tool not in DIAG_TOOLS:
        return jsonify({'error': f'unsupported tool: {tool}'}), 400

    # Validate target format
    if not ALLOWED_TARGETS_PATTERN.match(target):
        return jsonify({'error': 'invalid target format'}), 400

    # Build command
    cmd_path = DIAG_TOOLS[tool]

    if tool == 'ping':
        # The options field allows passing additional flags like -W timeout
        cmd = f"{cmd_path} -c {count} {options} {target}"
    elif tool == 'dig':
        cmd = f"{cmd_path} {options} {target}"
    elif tool == 'traceroute':
        cmd = f"{cmd_path} {options} {target}"
    else:
        cmd = f"{cmd_path} {options} {target}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=30,
            env={'PATH': '/usr/bin:/bin', 'HOME': '/tmp'}
        )
        return jsonify({
            'stdout': result.stdout,
            'stderr': result.stderr,
            'returncode': result.returncode
        })
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'command timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
